const $=s=>document.querySelector(s);let db,recipes=[],category='Todas',editing=null,urls=[],searchByIngredient=false;
const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4000)}
function transaction(mode,run){return new Promise((resolve,reject)=>{const t=db.transaction('recipes',mode);let result;run(t.objectStore('recipes'),v=>result=v);t.oncomplete=()=>resolve(result);t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error||new Error('Não foi possível salvar.'))})}
async function load(){recipes=await transaction('readonly',(s,set)=>{const r=s.getAll();r.onsuccess=()=>set(r.result)});render()}
function url(blob){const u=URL.createObjectURL(blob);urls.push(u);return u}
function render(){urls.forEach(u=>URL.revokeObjectURL(u));urls=[];$('#count').textContent=recipes.length;const shown=selectRecipes(recipes,$('#search').value,searchByIngredient,category);$('#recipes').innerHTML=shown.length?shown.map(r=>`<article class="card"><button class="card-open" data-open="${r.id}" aria-label="Abrir ${esc(r.title)}">${r.photo?`<img src="${url(r.photo)}" alt="${esc(r.title)}">`:'<div class="placeholder" aria-hidden="true">🥣</div>'}<div class="card-body"><h3>${esc(r.title)}</h3><div class="meta">${r.video?'▶ Ver receita e vídeo':'Ver receita →'}</div></div></button><button class="heart" data-favorite="${r.id}" aria-label="${r.favorite?'Remover dos':'Adicionar aos'} favoritos">${r.favorite?'♥':'♡'}</button></article>`).join(''):`<div class="empty"><div class="symbol">♡</div><h3>${recipes.length?'Nenhuma receita por aqui':'Seu livro começa aqui'}</h3><p>${recipes.length?'Tente outra busca ou categoria.':'Qual receita da Maria Carmela tem gosto de infância? Guarde os ingredientes, o preparo e sua lembrança favorita.'}</p>${recipes.length?'':'<button class="primary" id="empty-new">＋ Adicionar minha primeira receita</button>'}</div>`;$('#empty-new')?.addEventListener('click',()=>editor());}
function editor(r){editing=r||null;$('#form').reset();$('#editor-title').textContent=r?'Editar receita':'Adicionar receita';$('#form-error').textContent='';if(r)for(const k of ['title','category','time','yield','ingredients','steps','notes'])$('#form').elements[k].value=r[k]||'';$('#editor').showModal()}
function detail(r){const lines=(text,tag)=>`<${tag}>${text.split('\n').filter(x=>x.trim()).map(x=>`<li>${esc(x)}</li>`).join('')}</${tag}>`;$('#detail-content').innerHTML=`<div class="modal-head"><span class="eyebrow">${esc(r.category)}</span><button class="close" aria-label="Fechar">×</button></div><h2>${esc(r.title)}</h2>${r.photo?`<img class="detail-image" src="${url(r.photo)}" alt="${esc(r.title)}">`:''}<p class="meta">${esc(r.time)}${r.time&&r.yield?' · ':''}${esc(r.yield)}</p><div class="detail-copy"><h3>Ingredientes</h3>${lines(r.ingredients,'ul')}<h3>Modo de preparo</h3>${lines(r.steps,'ol')}${r.video?`<h3>Na nossa cozinha</h3><video controls preload="metadata" src="${url(r.video)}"></video>`:''}${r.notes?`<h3>Dicas e memórias da vó</h3><div class="memory">${esc(r.notes)}</div>`:''}</div><div class="actions"><button class="quiet danger" id="delete">Excluir</button><button class="primary" id="edit">Editar receita</button></div>`;$('#detail .close').onclick=()=>$('#detail').close();$('#edit').onclick=()=>{$('#detail').close();editor(r)};$('#delete').onclick=async()=>{if(!confirm('Excluir esta receita do seu livro?'))return;try{await transaction('readwrite',s=>s.delete(r.id));$('#detail').close();await load();toast('Receita excluída.')}catch(e){toast('Não foi possível excluir a receita.')}};$('#detail').showModal()}
$('#new').onclick=()=>editor();document.querySelectorAll('#editor .close').forEach(b=>b.onclick=()=>$('#editor').close());$('#search').oninput=render;$('#filters').onclick=e=>{const b=e.target.closest('[data-category]');if(!b)return;category=b.dataset.category;document.querySelectorAll('#filters button').forEach(x=>x.classList.toggle('active',x===b));render()};$('#recipes').onclick=async e=>{const o=e.target.closest('[data-open]'),f=e.target.closest('[data-favorite]');if(o)detail(recipes.find(r=>r.id===o.dataset.open));if(f){const r=recipes.find(r=>r.id===f.dataset.favorite);try{await transaction('readwrite',s=>s.put({...r,favorite:!r.favorite}));await load()}catch(e){toast('Não foi possível salvar o favorito.')}}};
$('#form').onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('[type=submit]');b.disabled=true;try{const photo=f.elements.photo.files[0],video=f.elements.video.files[0];if(photo&&!photo.type.startsWith('image/'))throw new Error('Escolha um arquivo de imagem.');if(video&&!video.type.startsWith('video/'))throw new Error('Escolha um arquivo de vídeo.');if(video?.size>100*1024*1024)throw new Error('Escolha um vídeo de até 100 MB.');const r={id:editing?.id||crypto.randomUUID(),favorite:editing?.favorite||false,photo:photo||editing?.photo||null,video:video||editing?.video||null};for(const k of ['title','category','time','yield','ingredients','steps','notes'])r[k]=f.elements[k].value.trim();if(!r.title||!r.ingredients||!r.steps)throw new Error('Preencha nome, ingredientes e modo de preparo.');await transaction('readwrite',s=>s.put(r));$('#editor').close();await load();toast('Receita guardada com carinho.')}catch(error){$('#form-error').textContent=error.name==='QuotaExceededError'?'O armazenamento está cheio. Exporte seu livro e use um vídeo menor.':error.message||'Não foi possível salvar.'}finally{b.disabled=false}};
const dataURL=blob=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob)});
$('#backup').onclick=async()=>{const button=$('#backup');button.disabled=true;try{const exported=[];for(const r of recipes)exported.push({...r,photo:r.photo?await dataURL(r.photo):null,video:r.video?await dataURL(r.video):null});const blob=new Blob([JSON.stringify({format:'maria-carmela-v1',recipes:exported})],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='receitas-maria-carmela-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Cópia do livro exportada.')}catch(e){toast('Não foi possível exportar o livro.')}finally{button.disabled=false}};
$('#import').onclick=()=>$('#import-file').click();$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const book=JSON.parse(await file.text());if(book.format!=='maria-carmela-v1'||!Array.isArray(book.recipes))throw new Error('Este arquivo não é um livro Maria Carmela.');const imported=[];for(const r of book.recipes){if(!r||!['title','ingredients','steps','category'].every(k=>typeof r[k]==='string')||!r.title.trim())throw new Error('O livro contém uma receita inválida.');const media=async(v,type)=>{if(!v)return null;if(typeof v!=='string'||!v.startsWith('data:'+type+'/')||!v.includes(';base64,'))throw new Error('O livro contém uma mídia inválida.');return(await fetch(v)).blob()};imported.push({...r,id:crypto.randomUUID(),photo:await media(r.photo,'image'),video:await media(r.video,'video')})}if(!confirm(`Adicionar ${imported.length} receita(s) ao seu livro? As receitas atuais serão mantidas.`))return;await transaction('readwrite',s=>imported.forEach(r=>s.put(r)));await load();toast('Receitas importadas.')}catch(err){toast(err.message||'Não foi possível importar.')}finally{e.target.value=''}};
const request=indexedDB.open('maria-carmela',1);request.onupgradeneeded=()=>request.result.createObjectStore('recipes',{keyPath:'id'});request.onsuccess=async()=>{db=request.result;try{await load()}catch(e){toast('Não foi possível abrir seu livro.')}};request.onerror=()=>toast('Ative o armazenamento do navegador para guardar receitas.');

for(const id of ['hero-new','collection-new','mobile-new'])if($('#'+id))$('#'+id).onclick=()=>editor();
function pickCategory(value){category=value;document.querySelectorAll('#filters button').forEach(b=>b.classList.toggle('active',b.dataset.category===value));render();$('#collection').scrollIntoView({behavior:'smooth',block:'start'})}
document.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>pickCategory(b.dataset.pick));document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>pickCategory(b.dataset.nav));document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();$('#search').focus()}});

function normalizeSearch(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR')}
function selectRecipes(items,query,byIngredient,cat){const terms=normalizeSearch(query).trim().split(/\s+/).filter(Boolean);return items.filter(r=>(cat==='Todas'||(cat==='Favoritas'?r.favorite:r.category===cat))&&terms.every(term=>normalizeSearch(byIngredient?r.ingredients:[r.title,r.ingredients].join(' ')).includes(term))).sort((a,b)=>a.title.localeCompare(b.title,'pt-BR',{sensitivity:'base',numeric:true}));}
function changeSearchMode(ingredient){searchByIngredient=ingredient;category='Todas';$('#sort-az').classList.toggle('active',!ingredient);$('#by-ingredient').classList.toggle('active',ingredient);$('#sort-az').setAttribute('aria-pressed',String(!ingredient));$('#by-ingredient').setAttribute('aria-pressed',String(ingredient));$('#search').placeholder=ingredient?'Pesquisar ingredientes: farinha, leite…':'Pesquisar receita ou ingrediente…';$('#search-mode').textContent=ingredient?'Busca pelos ingredientes da receita':'Nome ou ingrediente · A–Z';render();if(ingredient)$('#search').focus();}
$('#sort-az').onclick=()=>changeSearchMode(false);$('#by-ingredient').onclick=()=>changeSearchMode(true);$('#search-button').onclick=()=>{render();$('#search').focus()};
